69	/// Selects the highest-versioned tag matching `template` out of a full tag
70	/// list previously obtained via [`fetch_all_tags`], reusing a `cache` of
71	/// already-compiled/already-scanned candidates keyed by `template.glob()`
72	/// -- a `[[package-set]]` rule with a fixed (non-`{name}`) `tag-template`
73	/// string applies the identical template to every matching package, so
74	/// without this cache `TagIndex::build`'s per-package loop would recompile
75	/// the same `globset::Glob` and rescan the full tag list once per package
76	/// sharing that template, instead of once per distinct template.
77	fn select_from_tags_cached<'a>(
78	    all_tags: &'a [String],
79	    template: &TagTemplate,
80	    grammar: VersionGrammar,
81	    cache: &mut std::collections::HashMap<String, Vec<&'a str>>,
82	) -> Result<LastTagSelection, GraphError> {
83	    let glob = template.glob();
84	    let candidates = match cache.get(&glob) {
85	        Some(cached) => cached.clone(),
86	        None => {
87	            let matched = matching_tags(all_tags, template)?;
88	            cache.insert(glob, matched.clone());
89	            matched
90	        }
91	    };
92	    select_last_tag(template, grammar, candidates).map_err(GraphError::from)
93	}
