95	/// Keeps the chosen tag and records each skipped-tag warning once, however many packages scan the same tags.
96	fn take_chosen(selection: LastTagSelection, diagnostics: &mut Vec<Diagnostic>) -> Option<LastTag> {
97	    for diagnostic in selection.skipped {
98	        if !diagnostics.iter().any(|seen| seen.message == diagnostic.message) {
99	            diagnostics.push(diagnostic);
100	        }
101	    }
102	    selection.chosen
103	}
