105	/// The higher-versioned of two tags found for one package; `first` wins a tie.
106	fn newest(first: Option<LastTag>, second: Option<LastTag>) -> Option<LastTag> {
107	    match (first, second) {
108	        (Some(first), Some(second)) => {
109	            let newer = second
110	                .version
111	                .compare(&first.version)
112	                .is_ok_and(std::cmp::Ordering::is_gt);
113	            Some(if newer { second } else { first })
114	        }
115	        (first, second) => first.or(second),
116	    }
117	}
