119	/// E101 when a package's default template (`{name}@{version}`) is also another package's template.
120	fn reject_shared_default_templates<D: DependencyResolver>(graph: &D) -> Result<(), GraphError> {
121	    let mut by_template: BTreeMap<String, (bool, Vec<PackageId>)> = BTreeMap::new();
122	    for pkg in graph.packages() {
123	        let tmpl = pkg
124	            .tag_template
125	            .clone()
126	            .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
127	        let (has_default, ids) = by_template.entry(tmpl.as_str()).or_default();
128	        *has_default |= pkg.tag_template.is_none();
129	        ids.push(pkg.id.clone());
130	    }
131	    match by_template
132	        .into_iter()
133	        .find(|(_, (has_default, ids))| *has_default && ids.len() > 1)
134	    {
135	        Some((template, (_, packages))) => Err(GraphError::SharedDefaultTagTemplate { template, packages }),
136	        None => Ok(()),
137	    }
138	}
