263	    pub fn template(&self, id: &PackageId) -> &TagTemplate {
264	        &self.templates[id]
265	    }
266	
267	    pub fn pre_cursor(&self, id: &PackageId) -> Option<&CommitSha> {
268	        self.pre_cursor.get(id).and_then(|opt| opt.as_ref())
269	    }
