271	    /// Returns whether `tag_name` is present in the raw tag list fetched
272	    /// during `build` -- an exact match, not a glob. Lets callers checking
273	    /// tag existence once per package (e.g. `derive_unreleased_decision`)
274	    /// consult this in-memory set instead of shelling out to `git` again
275	    /// for each one.
276	    pub fn contains_tag(&self, tag_name: &str) -> bool {
277	        self.all_tags.contains(tag_name)
278	    }
