280	    /// Constructs an empty `TagIndex` with no packages or tags — useful in
281	    /// unit tests that do not exercise tag-based logic.
282	    pub fn empty() -> Self {
283	        TagIndex {
284	            last: BTreeMap::new(),
285	            templates: BTreeMap::new(),
286	            pre_cursor: BTreeMap::new(),
287	            all_tags: std::collections::BTreeSet::new(),
288	            diagnostics: Vec::new(),
289	        }
290	    }
291	}
