460	    /// Spec: a `TagTemplate` whose glob fails to compile must make
461	    /// `matching_tags` return `Err`, not silently disable filtering and
462	    /// match every tag in the repo. `TagTemplate::parse` only rejects
463	    /// `*`/`?`/`[`/`]` in literal text -- it does not reject unbalanced
464	    /// `{`/`}`, so a template like `pkg-a@{version}{oops` parses
465	    /// successfully but renders the glob `pkg-a@*{oops`, which `globset`
466	    /// cannot compile (unclosed alternate group). This is a real
467	    /// correctness risk for release tagging: silently matching every tag
468	    /// could make "last tag" resolution pick an unrelated package's tag.
469	    #[test]
470	    fn test_matching_tags_rejects_malformed_glob_instead_of_matching_everything() {
471	        let all = vec![
472	            "pkg-a@1.0.0".to_string(),
473	            "totally-unrelated-tag".to_string(),
474	            "another-unrelated-tag".to_string(),
475	        ];
476	        let tmpl = TagTemplate::parse("pkg-a@{version}{oops").unwrap();
477	        // Sanity-check the premise: this template's glob really is
478	        // uncompilable.
479	        assert!(globset::Glob::new(&tmpl.glob()).is_err());
480	
481	        let result = matching_tags(&all, &tmpl);
482	
483	        assert!(
484	            matches!(
485	                result,
486	                Err(GraphError::Vcs(callisto_model::vcs::VcsError::InvalidGlob { .. }))
487	            ),
488	            "malformed glob must be surfaced as Err, not silently match every tag; got {result:?}"
489	        );
490	    }
